import numpy as np, torch, model
net=model.load()
Wd=torch.tensor(np.load('contrast_c3_out_act_k10.npy')).float().reshape(-1); bd=-7.0343
print(Wd.shape)
def run(xi,c,dv=None,lo=0,hi=0,thr=0.0):
    x=xi.clone(); fires=torch.zeros(x.shape[0])
    for k in range(20):
        t=torch.full((x.shape[0],),1-k/20)
        v,A=net.velocity(x,t,c,("out_act",),count=False)
        z=A["out_act"]@Wd+bd
        if 8<=k<=10: fires+= (z>0).float()
        if dv is not None and lo<=k<hi:
            v=v+((z>thr).float()[:,None])*dv
        x=x-v/20
    return x.numpy(), fires.numpy()
torch.manual_seed(5); M=3000; xt=torch.randn(M,2)
cs=np.linspace(0.05,0.95,10)
base={};lab={}
for cv in cs:
    a,f=run(xt,torch.full((M,),cv)); base[cv]=a; lab[cv]=f>=2
print('base target share',[round(lab[cv].mean(),3) for cv in cs])
def tgt(cv,a):
    T=base[cv][lab[cv]]
    d=np.linalg.norm(a[:,None,:]-T[None],axis=2).min(1); return d<0.4
for (lo,hi) in [(0,6),(4,10),(6,11)]:
  for ang in [-35,0,35]:
    for D in [1.5,3.0]:
      dif=np.array([2.797,-1.933]); dif/=np.linalg.norm(dif)
      R=np.array([[np.cos(np.radians(ang)),-np.sin(np.radians(ang))],[np.sin(np.radians(ang)),np.cos(np.radians(ang))]])
      d=R@(-dif)   # direction x should move: opposite target velocity diff in x-motion terms
      # x moves by -v/20; target has v diff +dif => x moves along -dif extra; to undo, move x along +dif
      d=R@dif
      dv=torch.tensor(-d*D*20/(hi-lo),dtype=torch.float32)
      tb=[];ta=[];mv=[]
      for cv in cs:
        a,_=run(xt,torch.full((M,),cv),dv,lo,hi)
        tb.append(lab[cv].mean()); ta.append(tgt(cv,a).mean())
        mv.append(np.mean((np.linalg.norm(a-base[cv],axis=1)>0.5)&~lab[cv]))
      print(f'win={lo}:{hi} ang={ang} D={D} tgt {np.mean(tb):.3f}->{np.mean(ta):.3f} by c {np.round(ta,2)} nontarget moved {np.mean(mv):.3f}',flush=True)

import numpy as np, torch, model
net=model.load()
Wd=torch.tensor(np.load('contrast_c3_out_act_k10.npy')).float().reshape(-1); bd=-7.0343
Jm=torch.tensor([[0.,-1.],[1.,0.]])
def run(xi,c,G=None,lo=0,hi=0):
    x=xi.clone(); fires=torch.zeros(x.shape[0])
    for k in range(20):
        t=torch.full((x.shape[0],),1-k/20)
        v,A=net.velocity(x,t,c,("out_act",),count=False)
        z=A["out_act"]@Wd+bd
        if 8<=k<=10: fires+= (z>0).float()
        if G is not None and lo<=k<hi:
            v=v+((z>0).float()[:,None])*(x@G.T)
        x=x-v/20
    return x.numpy(), fires.numpy()
torch.manual_seed(5); M=3000; xt=torch.randn(M,2)
cs=np.linspace(0.05,0.95,10)
base={};lab={}
for cv in cs:
    a,f=run(xt,torch.full((M,),cv)); base[cv]=a; lab[cv]=f>=2
allT=np.concatenate([base[cv] for cv in cs])
def tgt(cv,a):
    T=base[cv][lab[cv]]
    d=np.linalg.norm(a[:,None,:]-T[None],axis=2).min(1); return d<0.4
for (lo,hi) in [(4,11),(6,11),(8,12)]:
  for kap in [-40,-20,20,40]:
      G=-kap*Jm  # dv = -kap J x  => x += kap/20 J x
      ta=[];mv=[];typ=[]
      for cv in cs:
        a,_=run(xt,torch.full((M,),cv),G,lo,hi)
        ta.append(tgt(cv,a).mean())
        mv.append(np.mean((np.linalg.norm(a-base[cv],axis=1)>0.5)&~lab[cv]))
        # typicality: moved targets land near some base action at same c
        dd=np.linalg.norm(a[lab[cv]][:,None]-base[cv][None],axis=2).min(1); typ.append(np.mean(dd<0.3))
      print(f'win={lo}:{hi} kap={kap} tgt 0.100->{np.mean(ta):.3f} by c {np.round(ta,2)} ntmoved {np.mean(mv):.3f} typical {np.mean(typ):.2f}',flush=True)
